#include "ViewerRuntime.h"
void CaptureV0412Ui(const fs::path&,HWND);
void RunV0516UiTests(const fs::path& root,std::ostream& report){
    auto check=[&](bool ok,const char* text){if(!ok)throw std::runtime_error(text);report<<"PASS: v0516 "<<text<<std::endl;};
    auto rect=[](HWND h){RECT r{};GetWindowRect(h,&r);return r;};
    KillTimer(app.window,RecordTimer);struct Restore{~Restore(){SetAppFont(L"",10,false);SetTimer(app.window,RecordTimer,500,nullptr);}} restore;
    SetAppFont(L"",10,false);app.layout=L"bottom";app.sideHeight=220;TabCtrl_SetCurSel(app.metadataTabs,0);ResetSideScroll();
    app.previewOriginalRequested=true;app.previewDedicated=true;app.previewPixels={400,1000,std::vector<BYTE>(400*1000*4)};
    for(size_t i=0;i<app.previewPixels.data.size();i+=4){app.previewPixels.data[i]=30;app.previewPixels.data[i+1]=110;app.previewPixels.data[i+2]=180;app.previewPixels.data[i+3]=255;}++app.previewRevision;
    PhotoSummary summary;summary.values[0]=L"portrait.png";ShowSummary(summary);
    for(int h:{140,220,320}){app.sideHeight=h;ResetSideScroll();Layout();RECT view{},image{};GetClientRect(app.side,&view);GetClientRect(app.preview,&image);check(image.bottom>0&&image.bottom<=view.bottom,"bottom portrait is bounded by viewport height after resizing");auto a=rect(app.preview),b=rect(app.verticalTabs[0]);check(a.right<b.left,"bounded portrait keeps metadata column separate");}
    app.previewPixels={1000,400,std::vector<BYTE>(1000*400*4,255)};++app.previewRevision;Layout();RECT landscape{};GetClientRect(app.preview,&landscape);check(std::abs(landscape.bottom-double(landscape.right)*.4)<=1,"bottom landscape retains aspect-based compact height");
    ShowFontDialog([&](HWND h){for(int i=0;i<8;++i){wchar_t value[80]{};SendDlgItemMessageW(h,2702,CB_GETLBTEXT,i,reinterpret_cast<LPARAM>(value));check(value==std::to_wstring(10+i*2),"font size choices contain numbers only");}SendMessageW(h,WM_COMMAND,IDCANCEL,0);});
    // Geometry/state checks only at other sizes; visual captures remain default face/10pt.
    ShowWindow(app.window,SW_HIDE);int previous=0;
    for(int pt:{10,12,14,16,18,20,22,24}){
        SetAppFont(L"",pt,false);int height=UiControlHeight();check(height>=UiLineHeight()+6&&height>=previous,"control height grows with font metrics");previous=height;
        for(int id:{Bookmarks,Options,Help,SortMenu,Browse}){auto h=AppControl(id);bool icon=(GetWindowLongPtrW(h,GWL_STYLE)&BS_TYPEMASK)==BS_OWNERDRAW;auto r=rect(h);check(icon==(pt>=18)&&r.bottom-r.top>=height,"five buttons switch at exactly 18pt and resize");if(icon)check(r.right-r.left==r.bottom-r.top,"icon buttons remain square");check(!Text(h).empty(),"icon buttons retain accessible names");}
        RECT client{};GetClientRect(app.window,&client);std::vector<RECT> controls;for(int id:{PathEdit,OpenPath,Browse,ResetView,HistoryBack,HistoryForward,History,SearchEdit,SearchButton,Bookmarks,Options,Help,SortMenu,Placement,RecordToggle,RecordIndicator}){auto r=rect(AppControl(id));MapWindowPoints(nullptr,app.window,reinterpret_cast<POINT*>(&r),2);check(r.left>=0&&r.right<=client.right&&r.top>=0,"toolbar stays inside main window");controls.push_back(r);}
        for(size_t i=0;i<controls.size();++i)for(size_t j=i+1;j<controls.size();++j){RECT overlap{};check(!IntersectRect(&overlap,&controls[i],&controls[j]),"toolbar controls do not overlap after font changes");}
        check(SendMessageW(app.history,CB_GETITEMHEIGHT,0,0)>=UiLineHeight(),"combo rows grow with the font");
    }
    app.mdbEnabled=true;app.categoryMode=2;app.personChoices={{L"name:test",L"Test person"}};Layout();auto category=GetDlgItem(app.window,3050);for(int id:{3100,3101,3102,3200}){auto r=rect(GetDlgItem(category,id));check(r.bottom-r.top>=UiControlHeight(),"category controls and person buttons grow with the font");}app.categoryMode=0;app.mdbEnabled=false;app.personChoices.clear();Layout();
    RECT originalWindow{};GetWindowRect(app.window,&originalWindow);
    for(int pt:{16,24}){SetAppFont(L"",pt,false);SetWindowPos(app.window,nullptr,0,0,620,700,SWP_NOMOVE|SWP_NOZORDER|SWP_NOACTIVATE);Layout();RECT client{};GetClientRect(app.window,&client);bool valid=true;std::vector<RECT> boxes;for(int id:{Bookmarks,Options,Help,SortMenu,Placement,RecordToggle}){auto r=rect(AppControl(id));MapWindowPoints(nullptr,app.window,reinterpret_cast<POINT*>(&r),2);valid=valid&&r.left>=0&&r.right<=client.right;boxes.push_back(r);}for(size_t i=0;i<boxes.size();++i)for(size_t j=i+1;j<boxes.size();++j){RECT overlap{};valid=valid&&!IntersectRect(&overlap,&boxes[i],&boxes[j]);}check(valid,"large font toolbar wraps without overlap in a narrow window");}
    SetWindowPos(app.window,nullptr,0,0,originalWindow.right-originalWindow.left,originalWindow.bottom-originalWindow.top,SWP_NOMOVE|SWP_NOZORDER|SWP_NOACTIVATE);
    SetAppFont(L"",24,false);
    for(int resource=2006;resource<=2010;++resource){auto found=FindResourceW(GetModuleHandleW(nullptr),MAKEINTRESOURCEW(resource),RT_RCDATA);check(found&&SizeofResource(GetModuleHandleW(nullptr),found)>0,"requested icon asset is embedded");}
    auto fixture=CreateWindowExW(0,L"STATIC",L"font layout fixture",WS_POPUP,0,0,610,586,app.window,nullptr,GetModuleHandleW(nullptr),nullptr);auto button=CreateWindowExW(0,L"BUTTON",L"キャンセル",WS_CHILD,488,546,110,28,fixture,reinterpret_cast<HMENU>(IDCANCEL),GetModuleHandleW(nullptr),nullptr);ApplyUiFont(fixture);ScaleUiDialog(fixture);auto scaled=rect(button);check(scaled.bottom-scaled.top>=UiControlHeight(),"fixed-dialog buttons scale with text");MONITORINFO monitor{sizeof(monitor)};GetMonitorInfoW(MonitorFromWindow(fixture,MONITOR_DEFAULTTONEAREST),&monitor);auto bounds=rect(fixture);check(bounds.left>=monitor.rcWork.left&&bounds.top>=monitor.rcWork.top&&bounds.right<=monitor.rcWork.right&&bounds.bottom<=monitor.rcWork.bottom,"scaled fixed dialog is bounded by monitor work area");if(GetWindowLongPtrW(fixture,GWL_STYLE)&WS_VSCROLL){SendMessageW(fixture,WM_VSCROLL,SB_BOTTOM,0);check(GetScrollPos(fixture,SB_VERT)>0,"oversized dialog scrolls to its bottom controls");}DestroyWindow(fixture);
    SetAppFont(L"",10,false);app.layout=L"bottom";app.sideHeight=220;app.previewPixels={400,1000,std::vector<BYTE>(400*1000*4)};for(size_t i=0;i<app.previewPixels.data.size();i+=4){app.previewPixels.data[i]=30;app.previewPixels.data[i+1]=110;app.previewPixels.data[i+2]=180;app.previewPixels.data[i+3]=255;}++app.previewRevision;ResetSideScroll();SendMessageW(app.placement,CB_SETCURSEL,2,0);
    for(bool dark:{false,true}){app.darkTheme=dark;ApplyTheme();Layout();CaptureV0412Ui(root/(dark?L"v0516-bottom-dark.png":L"v0516-bottom-light.png"),app.window);}
    app.darkTheme=false;app.layout=L"right";app.sideWidth=400;app.sideHeight=300;app.previewPixels={};app.previewDedicated=false;app.previewOriginalRequested=false;++app.previewRevision;ShowSummary({});ResetSideScroll();ApplyTheme();Layout();
}
int FontLayoutTest(){auto root=app.settings.parent_path();std::ofstream report(root/L"v0516-result.txt");try{RunV0516UiTests(root,report);report<<"ALL PASSED\n";return 0;}catch(const std::exception& e){report<<"FAIL: "<<e.what()<<std::endl;return 1;}}
